use std::fs

fn digit_val(c: char) -> int {
    let d = c as int
    if d >= 48 && d <= 57 {
        d - 48
    } else if d >= 65 && d <= 90 {
        d - 55
    } else {
        d - 87
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let dv: Vec<char> = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect()
    for line in text.lines() {
        let mut parts: Vec<string> = []
        for p in line.split_whitespace() {
            parts.push(p.to_string())
        }
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse::<int>().unwrap_or(10)
        let to: int = parts[2].parse::<int>().unwrap_or(10)
        let mut v: int = 0
        for c in parts[0].chars() {
            v = v * from + digit_val(c)
        }
        if v == 0 {
            println("0")
            continue
        }
        let mut out: Vec<char> = []
        while v > 0 {
            let r = v % to
            out.push(dv[r as usize])
            v = v / to
        }
        let mut s = ""
        let mut i: int = out.len() as int - 1
        while i >= 0 {
            s = s + out[i as usize].to_string()
            i = i - 1
        }
        println("${s}")
    }
}

